@pytest.mark.parametrize(("action", "group", "role"), CASES)
def test_ac42_the_listed_action_needs_a_fresh_second_factor(
    action: str, group: str, role: str
) -> None:
    assert action in RULES, f"{action} ({group}) is not in the permission matrix"
    assert RULES[action].mfa_recent, f"{action} lacks mfa_recent: required"
    assert role, f"{action}: no human role may, so nothing shows the MFA rule"


@pytest.mark.parametrize(("action", "group", "role"), CASES)
@pytest.mark.parametrize(
    ("freshness", "want"), [("fresh", "allow"), ("stale", "deny"), ("none", "deny")]
)
async def test_ac42_authorise_refuses_without_a_fresh_second_factor(
    monkeypatch: pytest.MonkeyPatch,
    action: str,
    group: str,
    role: str,
    freshness: Freshness,
    want: str,
) -> None:
    assert await mfa_outcome(monkeypatch, action, role, freshness) == want


def test_ac42_the_routes_declaring_a_listed_action_are_unchanged() -> None:
    guarded, _ = served(app())
    assert [row for row in guarded if row[2] in LISTED] == list(ROUTES)
